/**
 * @typedef EonRow
 * @type {object}
 * @property {Date} timestamp Timestmap
 * @property {number} priceExclVat Price excl. VAT
 * @property {number} priceInclVat Price incl. VAT
 * @property {boolean} definitive If price might change
 * @property {boolean} padded If padded
 * @property {string} area Area code
 */

const dataPointsExcl = msg.payload.map((/** @type {EonRow} */ item) => {
    // OTLP requires timestamps in Nanoseconds (Epoch ms * 1,000,000)
    const timeUnixNano = (new Date(item.timestamp).getTime()) * 1000000;
    //const timeUnixNano = `${new Date(item.timestamp).getTime()}000000`;

    return {
        "timeUnixNano": timeUnixNano.toString(),
        "asDouble": item.priceExclVat,
        "attributes": [
            { "key": "price_area", "value": { "stringValue": item.area || "" } },
        ]
    };
});

const dataPointsIncl = msg.payload.map((/** @type {EonRow} */ item) => {
    // OTLP requires timestamps in Nanoseconds (Epoch ms * 1,000,000)
    const timeUnixNano = (new Date(item.timestamp).getTime()) * 1000000;
    //const timeUnixNano = `${new Date(item.timestamp).getTime()}000000`;

    return {
        "timeUnixNano": timeUnixNano.toString(),
        "asDouble": item.priceInclVat,
        "attributes": [
            { "key": "price_area", "value": { "stringValue": item.area || "" } },
        ]
    };
});

msg.payload = {
    "resourceMetrics": [
        {
            "resource": {
                "attributes": [
                    { 
                        "key": "service.name",
                        "value": {
                            "stringValue": "eon-fetcher"
                        }
                    },
                    { 
                        "key": "host.name",
                        "value": {
                            "stringValue": "nodered-home"
                        }
                    }
                ]
            },
            "scopeMetrics": [
                {
                    "scope": {
                        "name": "eon.price.exporter",
                        "version": "1.0.0"
                    },
                    "metrics": [
                        {
                            "name": "eon_electricity_price_excl_vat",
                            "description": "E.ON spot electricity price per kWh (excl.VAT)",
                            "unit": "SEK/kWh",
                            "gauge": {
                                "dataPoints": dataPointsExcl,
                            }
                        },
                        {
                            "name": "eon_electricity_price_incl_vat",
                            "description": "E.ON spot electricity price per kWh (incl.VAT)",
                            "unit": "SEK/kWh",
                            "gauge": {
                                "dataPoints": dataPointsIncl
                            }
                        }
                    ]
                }
            ]
        }
    ]
};

node.status({
    fill: "green",
    shape: "ring",
    text: `Sent ${dataPointsExcl.length + dataPointsIncl.length} datapoints`,
});

return msg;

const tomorrow = new Date();
tomorrow.setDate(tomorrow.getDate() + 1);
// sv-SE formats as YYYY-MM-DD, in local time.
msg.date = tomorrow.toLocaleDateString('sv-SE');
return msg;
